"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[8235],{3331:(e,r,t)=>{t.d(r,{R:()=>o,x:()=>l});var s=t(36672);const n={},i=s.createContext(n);function o(e){const r=s.useContext(i);return s.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function l(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:o(e.components),s.createElement(i.Provider,{value:r},e.children)}},60602:(e,r,t)=>{t.r(r),t.d(r,{assets:()=>a,contentTitle:()=>l,default:()=>g,frontMatter:()=>o,metadata:()=>s,toc:()=>d});const s=JSON.parse('{"id":"2023/04/02","title":"2023-04-02","description":"Amazon Echo-enheter lagrer WiFi-passord i klartekst, noe som gj\xf8r dem s\xe5rbare for fysiske tilgangsangrep","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/02.md","sourceDirName":"2023/04","slug":"/2023/04/02","permalink":"/nb/2023/04/02","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/02.md","tags":[],"version":"current","frontMatter":{"localized_date":"2. april 2023","top_news":"Amazon Echo-enheter lagrer WiFi-passord i klartekst, noe som gj\xf8r dem s\xe5rbare for fysiske tilgangsangrep"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-03","permalink":"/nb/2023/04/03"},"next":{"title":"01","permalink":"/nb/2023/04/01"}}');var n=t(23420),i=t(3331);const o={localized_date:"2. april 2023",top_news:"Amazon Echo-enheter lagrer WiFi-passord i klartekst, noe som gj\xf8r dem s\xe5rbare for fysiske tilgangsangrep"},l="2023-04-02",a={},d=[{value:"Amazon Echo-enheter lagrer WiFi-passord i klartekst, noe som gj\xf8r dem s\xe5rbare for fysiske tilgangsangrep",id:"amazon-echo-enheter-lagrer-wifi-passord-i-klartekst-noe-som-gj\xf8r-dem-s\xe5rbare-for-fysiske-tilgangsangrep",level:2},{value:"Google Drive innf\xf8rer filgrenser og kan stenge betalende kunder ute fra tjenesten",id:"google-drive-innf\xf8rer-filgrenser-og-kan-stenge-betalende-kunder-ute-fra-tjenesten",level:2},{value:"Guide to Logical Clock Designs for Reliable Event Ordering in Distributed Systems (veiledning til logisk klokkeutforming for p\xe5litelig hendelsesbestilling i distribuerte systemer).",id:"guide-to-logical-clock-designs-for-reliable-event-ordering-in-distributed-systems-veiledning-til-logisk-klokkeutforming-for-p\xe5litelig-hendelsesbestilling-i-distribuerte-systemer",level:2},{value:"Frankrikes 3034 km lange HexaTrek-sti er \xe5pen for gjennomg\xe5ende fotturer.",id:"frankrikes-3034-km-lange-hexatrek-sti-er-\xe5pen-for-gjennomg\xe5ende-fotturer",level:2},{value:"Utvikler Raph Levien g\xe5r fra Rust til C++.",id:"utvikler-raph-levien-g\xe5r-fra-rust-til-c",level:2},{value:"Coursemate: Forbinder selvl\xe6rende over hele verden for nettbasert l\xe6ring i fellesskap.",id:"coursemate-forbinder-selvl\xe6rende-over-hele-verden-for-nettbasert-l\xe6ring-i-fellesskap",level:2},{value:"Planter avgir lyder n\xe5r de blir stresset, noe som \xe5pner nye d\xf8rer for forst\xe5else",id:"planter-avgir-lyder-n\xe5r-de-blir-stresset-noe-som-\xe5pner-nye-d\xf8rer-for-forst\xe5else",level:2},{value:"Simulering av underjordisk BBS-system fra 1987: Chat, spill og e-post",id:"simulering-av-underjordisk-bbs-system-fra-1987-chat-spill-og-e-post",level:2},{value:"Google forsinker \xe5 sl\xe5 av Manifest V2 for Chrome-utvidelser",id:"google-forsinker-\xe5-sl\xe5-av-manifest-v2-for-chrome-utvidelser",level:2},{value:"Wine 8.5: Forbedret vkd3d, WinRT-tema og feilrettinger",id:"wine-85-forbedret-vkd3d-winrt-tema-og-feilrettinger",level:2},{value:"Resume-First ansettelsesprosess: Utnyttende og ineffektiv",id:"resume-first-ansettelsesprosess-utnyttende-og-ineffektiv",level:2},{value:"Ex-SpaceX Staff Found Dusinvis av Space Startups, Raise $ 3.6B",id:"ex-spacex-staff-found-dusinvis-av-space-startups-raise--36b",level:2},{value:"SpaceX&#39;s Starship flytter til oppskytingssted, oppskyting muligens 10. april.",id:"spacexs-starship-flytter-til-oppskytingssted-oppskyting-muligens-10-april",level:2},{value:"&#39;ccurl.sh&#39; gj\xf8r det mulig for cURL \xe5 bruke Chrome-informasjonskapsler p\xe5 en kortfattet m\xe5te.",id:"ccurlsh-gj\xf8r-det-mulig-for-curl-\xe5-bruke-chrome-informasjonskapsler-p\xe5-en-kortfattet-m\xe5te",level:2},{value:"MITs kurs om RNN-er og transformatorer for dyp l\xe6ring",id:"mits-kurs-om-rnn-er-og-transformatorer-for-dyp-l\xe6ring",level:2}];function k(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(r.header,{children:(0,n.jsx)(r.h1,{id:"2023-04-02",children:"2023-04-02"})}),"\n",(0,n.jsx)(r.h2,{id:"amazon-echo-enheter-lagrer-wifi-passord-i-klartekst-noe-som-gj\xf8r-dem-s\xe5rbare-for-fysiske-tilgangsangrep",children:"Amazon Echo-enheter lagrer WiFi-passord i klartekst, noe som gj\xf8r dem s\xe5rbare for fysiske tilgangsangrep"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Alexa, hva er wifi-passordet mitt?"}),".\nAmazon Echo-enheter lagrer WiFi-passord i klartekst, slik at angripere med fysisk tilgang relativt enkelt kan hente ut nettverkspassord. Dette utgj\xf8r en stor sikkerhetsrisiko for hoteller eller bedrifter som bruker enhetene p\xe5 sine interne eller private tr\xe5dl\xf8se nettverk, og gir angripere tilgang til alt annet utstyr p\xe5 nettverket, noe som potensielt bryter med personvernloven. Hashing av passord er en bransjestandard, og for et selskap som har solgt maskinvaren sin til millioner, er det helt uakseptabelt \xe5 ikke kryptere disse dataene. Enheten krypterer ikke API-n\xf8klene for Spotify zeroconf og eSDK API-er. Fysisk sikkerhet er avgj\xf8rende ved utforming av innebygd maskinvare, og Amazon m\xe5 ta tak i dette problemet for \xe5 forhindre fremtidige sikkerhetsbrudd.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35399590",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://dragon863.github.io/blog/alexa.html",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"google-drive-innf\xf8rer-filgrenser-og-kan-stenge-betalende-kunder-ute-fra-tjenesten",children:"Google Drive innf\xf8rer filgrenser og kan stenge betalende kunder ute fra tjenesten"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Google Drive gj\xf8r en overraskende utrulling av filgrenser, og l\xe5ser ut noen brukere."}),".\nGoogle Drive har innf\xf8rt en filgrense uten forvarsel, noe som potensielt kutter betalende kunder som er utestengt fra nye filopplastinger; Reddit-brukere har allerede klaget p\xe5 dette problemet de siste to m\xe5nedene. Den plutselige utrullingen av en filgrense er ikke oppf\xf8rt p\xe5 Google One- eller Google Workspace-plansider eller nevnt i st\xf8ttedokumenter. Det har ogs\xe5 hindret brukere i \xe5 bruke lagringsplassen de har kj\xf8pt, siden grensen hindrer dem i \xe5 bruke plassen. Begrensningen p\xe5 5 millioner filer i Google Disk anses verken som akseptabel eller rimelig av mange brukere, siden den ikke er dokumentert noe sted, og kostnadene ved \xe5 bruke Google Workspaces lagringsplan anses som ublu. Google hevder at grensen er en sikkerhetsforanstaltning for \xe5 hindre misbruk av systemet som kan p\xe5virke stabiliteten og sikkerheten, men slik kundekommunikasjon anses som d\xe5rlig.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35397071",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://arstechnica.com/gadgets/2023/03/google-drive-does-a-surprise-rollout-of-file-limits-locking-out-some-users/",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"guide-to-logical-clock-designs-for-reliable-event-ordering-in-distributed-systems-veiledning-til-logisk-klokkeutforming-for-p\xe5litelig-hendelsesbestilling-i-distribuerte-systemer",children:"Guide to Logical Clock Designs for Reliable Event Ordering in Distributed Systems (veiledning til logisk klokkeutforming for p\xe5litelig hendelsesbestilling i distribuerte systemer)."}),"\n",(0,n.jsxs)(r.p,{children:["**Clocks and Causality - Ordering Events in Distributed Systems (2022) **.\nLogiske klokker er avgj\xf8rende for \xe5 bestille hendelser i distribuerte systemer, med Lamport- og vektorklokker som popul\xe6re design. Lamport-klokker gir \xf8kende tall innenfor en node, mens vektorklokker sporer node-ID-er og respektive hendelses-ID-er for sammenligning av samtidige hendelser. Dotted Vector Clock og Vector Timestamps optimaliserer tidsstempelkontroller og gj\xf8r det mulig \xe5 bestille hendelser p\xe5 tvers av noder. Versjonsvektorer sporer dataversjoner i lagringsnoder med flere ledere. Lamport Causal Clock fanger opp kausalitet, men krever mer plass og tidskompleksitet. Total Order krever sekvensiell rekkef\xf8lge basert p\xe5 tidsmessige og kausale sammenhenger. Logiske klokker er avgj\xf8rende i samarbeidsredigeringsapplikasjoner. Azure Time Sync bruker PTP, mens AWS og Google Cloud bruker NTP. Artikkelen peker p\xe5 begrensningene ved \xe5 fors\xf8ke \xe5 betrakte tid som absolutt og fremhever betydningen av hendelsesbestilling i banktransaksjoner.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35399603",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://www.exhypothesi.com/clocks-and-causality/",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"frankrikes-3034-km-lange-hexatrek-sti-er-\xe5pen-for-gjennomg\xe5ende-fotturer",children:"Frankrikes 3034 km lange HexaTrek-sti er \xe5pen for gjennomg\xe5ende fotturer."}),"\n",(0,n.jsxs)(r.p,{children:["**Hexatrek: The long distance thru hike in France **Hexatrek: The long distance thru hike in France.\nFrankrikes 3034 km lange HexaTrek-sti er n\xe5 \xe5pen for gjennomg\xe5ende fotturer, og forbinder 14 nasjonalparker og krysser Romanias Via Transilvanica-sti.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35397051",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://en.hexatrek.com",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"utvikler-raph-levien-g\xe5r-fra-rust-til-c",children:"Utvikler Raph Levien g\xe5r fra Rust til C++."}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Flytter fra Rust til C++."}),".\nUtvikler Raph Levien kunngj\xf8r beslutningen om \xe5 flytte fra Rust til C++ p\xe5 grunn av begrensningene i f\xf8rstnevnte, for eksempel mangel p\xe5 byggesystemvalg og langsom innovasjonsfremgang, til tross for sikkerhetsgarantiene. Levien mener at han kan unng\xe5 sikkerhetsproblemer og at sikkerhetsfeil i minnet ikke er vesentlig mer skadelige enn andre feil, og at C++ utvikler seg raskt for \xe5 bli sikrere. Levien understreker viktigheten av fellesskap, og uttrykker bekymring for diskrimineringspolitikk og tilsynelatende anmassende Rust-forkjempere. Artikkelen er imidlertid satirisk, og noen lesere uttrykker interesse for C++ fremfor Rust.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35400047",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://raphlinus.github.io/rust/2023/04/01/rust-to-cpp.html",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"coursemate-forbinder-selvl\xe6rende-over-hele-verden-for-nettbasert-l\xe6ring-i-fellesskap",children:"Coursemate: Forbinder selvl\xe6rende over hele verden for nettbasert l\xe6ring i fellesskap."}),"\n",(0,n.jsxs)(r.p,{children:["**Vis Coursemate - f\xe5 kontakt med andre selvl\xe6rende **.\nCoursemate er en plattform der selvl\xe6rende kan koble seg til og samarbeide om nettkurs med jevnaldrende i sitt eget land eller rundt om i verden. Plattformen kan integreres med brukernes favorittnettkurs og tar mindre enn ett minutt \xe5 sette opp. Noen brukere foresl\xe5r at Coursemate kan dra nytte av mer spesifikke l\xe6ringsm\xe5l utover det n\xe5v\xe6rende fokuset p\xe5 frontend- og backend-emner. I tillegg vil brukerne gjerne se flere eksempler fra fellesskapet og muligheter for veiledning. Noen brukere foresl\xe5r ogs\xe5 \xe5 utvide filtreringen etter alder og land, slik at det blir mulig \xe5 filtrere etter interesse. Til tross for noe kritikk er nettstedet godt utf\xf8rt og oversiktlig. Noen brukere uttrykker et \xf8nske om en plattform for \xe5 komme i kontakt med eksperter som kan bidra til \xe5 forklare spesifikt kursinnhold.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35398480",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://www.coursem8.com/",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"planter-avgir-lyder-n\xe5r-de-blir-stresset-noe-som-\xe5pner-nye-d\xf8rer-for-forst\xe5else",children:"Planter avgir lyder n\xe5r de blir stresset, noe som \xe5pner nye d\xf8rer for forst\xe5else"}),"\n",(0,n.jsxs)(r.p,{children:["**Lyder som avgis av planter under stress er luftb\xe5rne og informative.\nPlanter kan avgi informative luftb\xe5rne lyder n\xe5r de er under stress, noe som \xe5pner muligheter for \xe5 forst\xe5 deres samspill med milj\xf8et. Dette nye feltet plantebioakustikk introduserte potensialet for akustisk kommunikasjon av planter, som kan oppdages av maskinl\xe6ringsmodeller og kan p\xe5virke landbruket utover tradisjonelle signaler.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35396156",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://www.cell.com/cell/fulltext/S0092-8674(23)00262-3",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"simulering-av-underjordisk-bbs-system-fra-1987-chat-spill-og-e-post",children:"Simulering av underjordisk BBS-system fra 1987: Chat, spill og e-post"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"ChatGPT simulerer BBS-systemet fra 1987"}),".\nArtikkelen diskuterer simulering av et BBS-system fra 1987, inkludert chat, spill og e-post. Brukerne kan opprette en konto, lese nyheter og dokumentasjon, se tekstfiler og kommunisere med andre brukere. Castle Quest, et tekstbasert spill, kan spilles p\xe5 systemet. ShareGPT gj\xf8r det mulig \xe5 dele kodesnutter i samtaler. Den historiske n\xf8yaktigheten til ChatGPTs resultater er tvilsom, men interessant. En bruker foresl\xe5r \xe5 simulere en BBS fra 1987 med tilleggsfunksjoner. Artikkelen gir et nostalgisk blikk p\xe5 fortidens teknologi.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35396165",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://sharegpt.com/c/ICZsSl7",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"google-forsinker-\xe5-sl\xe5-av-manifest-v2-for-chrome-utvidelser",children:"Google forsinker \xe5 sl\xe5 av Manifest V2 for Chrome-utvidelser"}),"\n",(0,n.jsxs)(r.p,{children:["**Pauser utfasingen av Manifest V2 **.\nGoogle har utsatt alle eksperimenter i januar for \xe5 sl\xe5 av Manifest V2 i pre-release-kanaler av Chrome og endringer i det utvalgte merket i Chrome Webstore, og det vil evaluere alle nedstr\xf8ms milep\xe6ler. Utviklere vil f\xe5 tilstrekkelig tid til \xe5 oppdatere og teste utvidelsene sine etter lanseringen av disse nye funksjonene f\xf8r Manifest V2 sl\xe5s av. Googles forpliktelse til \xe5 lansere Manifest V3 forventes \xe5 forbedre sikkerheten, personvernet og ytelsen for brukerne. Det kom tilbakemeldinger fra utviklermilj\xf8et om vanskeligheter med \xe5 bruke Manifest V3, og noen av disse har blitt adressert, men det er fortsatt forbedringer som m\xe5 gj\xf8res, og Google er fortsatt forpliktet til overgangen.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35402698",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://groups.google.com/a/chromium.org/g/chromium-extensions/c/zQ77HkGmK9E/m/HjaaCIG-BQAJ",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"wine-85-forbedret-vkd3d-winrt-tema-og-feilrettinger",children:"Wine 8.5: Forbedret vkd3d, WinRT-tema og feilrettinger"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Wine 8.5."}),"\nWine-versjon 8.5 kommer med forbedret vkd3d, WinRT Theme og feilrettinger, inkludert bedre feilrapportering i IDL-kompilatoren, st\xf8tte for UIA_IsOffscreenPropertyId til MSAA-leverand\xf8rer og fullstendig initialisering av i386 FPU-kontekst p\xe5 ARM64. Bin\xe6re pakker tilgjengelig for forskjellige distribusjoner, og kilde tilgjengelig direkte fra git-repositoriet. Feilrettinger inkluderer mscoree, imm32 og LDAP-binding.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35398643",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://www.winehq.org/announce/8.5",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"resume-first-ansettelsesprosess-utnyttende-og-ineffektiv",children:"Resume-First ansettelsesprosess: Utnyttende og ineffektiv"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Den som sender inn en CV har allerede tapt."}),".\nDen tradisjonelle ansettelsesprosessen med CV f\xf8rst er utnyttende og til syvende og sist ineffektiv, og arbeidsgivere bruker den hovedsakelig for \xe5 spare tid og kutte kostnader p\xe5 s\xf8kerens bekostning. CV-er kan ignoreres, og personlige anbefalinger og nettverk er mer effektive metoder for \xe5 sikre seg en jobb, utenom den mangelfulle og urettferdige prosessen. Akademiske ansettelser er utrolig demoraliserende, og nepotisme kan skape etiske problemer. Arbeidss\xf8kere m\xe5 gj\xf8re det de kan for \xe5 omg\xe5 systemet, men det er fortsatt n\xf8dvendig \xe5 ta CV-er p\xe5 alvor. Stillingen tilbyr verkt\xf8y for jobbs\xf8kere for \xe5 skille seg ut, inkludert \xe5 skrive et f\xf8lgebrev eller bruke et AI-verkt\xf8y for \xe5 skrive det p\xe5 to minutter.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35397271",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://www.residentcontrarian.com/p/he-who-submits-a-resume-has-already",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"ex-spacex-staff-found-dusinvis-av-space-startups-raise--36b",children:"Ex-SpaceX Staff Found Dusinvis av Space Startups, Raise $ 3.6B"}),"\n",(0,n.jsxs)(r.p,{children:["**SpaceX-alumner forgrener seg og former oppstarts\xf8konomien **.\nTidligere SpaceX-ansatte har funnet dusinvis av oppstartsbedrifter i verdensrommet og samlet inn 3,6 milliarder dollar for \xe5 drive innovasjon innen navigasjon i lav jordbane og levering av nyttelast. Medstifterne drar nytte av fellesskapet og h\xf8yrisikotoleransen som er etablert hos SpaceX, med oppskytingstjenester som ogs\xe5 bidrar til oppskyting av teknologiske prototyper, maskiner og navigasjonssatellitter. Software-as-a-service-industrien vokser og betjener \xf8kosystemet for oppstartsbedrifter i verdensrommet. Tempoet til NASA og Boeing kan dra nytte av \xe5 fremme en oppstartskultur ettersom gammel kode og gamle systemer holder de etablerte selskapene tilbake. Mulighetene innen romforskning gir likviditet i markedet, og investorer mottar millioner for risikable m\xe5neskudd. Noen kommentarer antyder at artikkelen f\xf8les som en pressemelding.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35404823",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://interactive.satellitetoday.com/via/april-2023/how-spacex-alums-are-branching-out-and-shaping-the-startup-economy/",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"spacexs-starship-flytter-til-oppskytingssted-oppskyting-muligens-10-april",children:"SpaceX's Starship flytter til oppskytingssted, oppskyting muligens 10. april."}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"SpaceX flytter Starship til oppskytingsstedet, og oppskytingen kan v\xe6re bare noen dager unna."})," **SpaceX flytter Starship til oppskytingsstedet, og oppskytingen kan v\xe6re bare noen dager unna.\nSpaceX har flyttet sitt Starship til et lanseringssted i S\xf8r-Texas, som kan v\xe6re klart for oppskyting s\xe5 snart som 10. april, i p\xe5vente av FAA-lisens. Den gigantiske, supertunge raketten er ment \xe5 tjene NASA som m\xe5nelandingsfart\xf8y for Artemis-m\xe5neoppdragene. SpaceX har investert over 1 milliard dollar i sitt oppskytings- og fangstt\xe5rn for \xe5 st\xf8tte Starship og Super Heavy, som de har utviklet mer forsiktig ved sitt anlegg i S\xf8r-Texas. Hvis dette lykkes, kan det gj\xf8re lav jordbane lettere tilgjengelig for fagfolk.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35405030",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://arstechnica.com/science/2023/04/spacex-moves-starship-to-launch-site-and-liftoff-could-be-just-days-away/",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"ccurlsh-gj\xf8r-det-mulig-for-curl-\xe5-bruke-chrome-informasjonskapsler-p\xe5-en-kortfattet-m\xe5te",children:"'ccurl.sh' gj\xf8r det mulig for cURL \xe5 bruke Chrome-informasjonskapsler p\xe5 en kortfattet m\xe5te."}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.strong,{children:"Vis Bruk informasjonskapsler fra Chrome (CDP) i cURL uten \xe5 kopiere og lime inn"}),'.\n\'ccurl.sh\' er et bash-skript som gj\xf8r det mulig for cURL \xe5 bruke Chrome-informasjonskapsler uten behov for et GUI-verkt\xf8y som Postman, ved \xe5 bruke Chrome DevTools-protokollen til \xe5 dumpe informasjonskapsler fra en bestemt fane i den lokale Chrome-instansen i overskriften til en cURL-kommando, og unng\xe5 lekkasje av informasjonskapsler til skallhistorikkfilen; Skriptet krever bash, websocat og jq for \xe5 kj\xf8re, og en fane med informasjonskapslene som skal brukes skal \xe5pnes i Chrome, som skal startes med "google-chrome-stable --remote-debugging-port=9222", og kan installeres ved \xe5 kopiere skriptet til "/usr/bin/ccurl" og gj\xf8re det kj\xf8rbart.\n',(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35399218",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://github.com/fipso/ccurl.sh",children:"Artikkel"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"mits-kurs-om-rnn-er-og-transformatorer-for-dyp-l\xe6ring",children:"MITs kurs om RNN-er og transformatorer for dyp l\xe6ring"}),"\n",(0,n.jsxs)(r.p,{children:["**MIT 6.S191: Tilbakevendende nevrale nettverk, transformatorer og oppmerksomhet **.\nMITs 6.S191-kurs dekker tilbakevendende nevrale nettverk (RNN), transformatorer og oppmerksomhet for dyp l\xe6ring, som vist p\xe5 YouTube. Kommentarene til videoen spenner fra \xe5 stille sp\xf8rsm\xe5l ved parameternavngivningskonvensjonene til \xe5 be om anbefalinger om hvor du kan l\xe6re nevrale nettverk og grunnleggende om dyp l\xe6ring. Kursets bruk av TensorFlow og opplasting av videoene til individuelle ansattes YouTube-kanaler diskuteres ogs\xe5.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35405338",children:"Discussion Service"}),", ",(0,n.jsx)(r.a,{href:"https://www.youtube.com/watch?v=ySEx_Bqxvvo",children:"Artikkel"}),"."]})]})}function g(e={}){const{wrapper:r}={...(0,i.R)(),...e.components};return r?(0,n.jsx)(r,{...e,children:(0,n.jsx)(k,{...e})}):k(e)}}}]);